public class IconDetector extends Detector implements BinaryResourceScanner {

    private static final int SIZE_MDPI = 48;

    @Override
    public void checkBinaryResource(@NonNull ResourceContext context) {
        ResourceFolderType type = context.getResourceFolderType();
        if (type != ResourceFolderType.MIPMAP) {
            return;
        }

        String name = context.file.getName();
        String base = LintUtils.getBaseName(name); // maybe not accessible? Use substring.
        if (!base.equals("ic_launcher") && !base.equals("ic_launcher_round")) {
            return;
        }

        DensityQualifier densityQualifier = context.getFolderConfiguration().getDensityQualifier();
        Density density = densityQualifier == null ? Density.MEDIUM : densityQualifier.getValue();
        if (density == Density.ANYDPI || density == Density.NODPI) {
            return;
        }

        int expected = getExpectedLauncherIconSize(density);
        if (expected <= 0) return;

        int width = context.getImageWidth();
        int height = context.getImageHeight();
        if (width == -1 || height == -1) return;

        if (width != expected || height != expected) {
            String message = String.format("The launcher icon is %dx%d px but should be %dx%d px for density %s", width, height, expected, expected, density.getResourceValue());
            context.report(ISSUE, context.getLocation(), message);
        }
    }

    private static int getExpectedLauncherIconSize(Density density) {
        switch (density) {
            case LOW: return 36;
            case MEDIUM: return 48;
            case HIGH: return 72;
            case XHIGH: return 96;
            case XXHIGH: return 144;
            case XXXHIGH: return 192;
            case TVDPI: return 64;
            default:
                // Compute from DPI ratio relative to mdpi.
                int dpi = density.getDpiValue();
                if (dpi > 0) {
                    return Math.round(SIZE_MDPI * dpi / 160f);
                }
                return -1;
        }
    }
```

